var STORE_M = [["Scrap", 10], ["Nonferrous", 239], ["Ferrous", 54], ["Steel", 10], ["Copper", 10], ["Polymer", 10], ["Wire", 72], ["Plates", 348], ["Circuits", 45], ["Data", 102]];
var SELL_M = { Nonferrous: [60, 120], Ferrous: [35, 70], Wire: [60, 240], Plates: [60, 900], Circuits: [27, 810], Data: [60, 300] };
var SELL_SEQ = ["Ferrous", "Nonferrous", "Wire", "Plates", "Circuits", "Data"];
var NODES = [["Efficient Cutters", "One cutting pulse gives 7 scrap instead of 5.", 4], ["Smart Buffers", "Every machine holds 6 more units of input, so short gaps do not halt it.", 8], ["Route Dispatch", "A newly connected link carries 8 more units at once.", 12]];
var BP = [{ id: "sorter", n: "Scrap sorter", cost: "20 scrap", scrap: 20, ferrous: 0 }, { id: "furnace", n: "Furnace", cost: "10 scrap " + U.mid + " 5 ferrous", scrap: 10, ferrous: 5 }];
// C9: the chip key table. A chip position comes from this table (its key), never from the painted
// node order, so a hidden key cannot shift the visible ones (fixes finding 14).
var CHIP_KEYS = [["scrap", "Scrap"], ["credits", "Credits"], ["store", "Store"], ["materials", "Materials"], ["ferrous", "Ferrous"], ["nonferrous", "Nonferrous"], ["wire", "Wire"], ["plates", "Plates"], ["circuits", "Circuits"], ["data", "Data"]];
function seed(n) { if (n === "mature") { return { tutorial: 9, scrap: 10, credits: 82, storeUnits: 900, capacity: 900, data: 102, drone: true, pulses: 6, overflow: 4, power: "0 of 8 units requested", busy: "97% busy (3/24 in transit)", waiting: 8, rows: STORE_M.map(function (r) { return [r[0], r[1]]; }), machines: MACH.map(function (m) { return Object.assign({}, m); }), known: [0, 1, 2], tick: 450330, links: 18 }; } return { tutorial: 0, scrap: 0, credits: 0, storeUnits: 0, capacity: 900, data: 0, drone: false, pulses: 0, overflow: 0, power: "0 of 8 units requested", busy: "0% busy (0/24 in transit)", waiting: 0, rows: [], machines: [], known: [], tick: 0, links: 0 }; }
function boot(n) { var name = n || "fresh"; var dn = (name === "reader") ? "mature" : name; S.data = seed(dn === "gate" ? "fresh" : dn); S.dest = "yard"; S.stack = []; S.hist = 0; S.machine = null; S.sub = 0; S.blueprint = null; S.ghost = 8; S.pressed = 0; S.log = []; S.lastFace = null; S.toast = null; S.importText = ""; S.importError = null; S.importPage = false; S.report = (name === "mature"); S.showAll = false; S.started = name !== "gate"; S.zoom = 1.6; S.role = (name === "reader") ? "reader" : "writer"; S.settings = { muted: false, textScale: 1, reducedMotion: false }; wire(); installApi(); render(); }
function el(id) { return document.getElementById(id); }
function btn(id, v, c, kind, dis, fn, why) { HAND[id] = fn || null; var cls = "f" + (kind === "p" ? " f--p" : "") + (kind === "on" ? " f--on" : ""); var o = "<button class=" + QD + cls + QD + " id=" + QD + id + QD + " onclick=" + QA + "RW47.tap(" + QD + id + QD + ")" + QA + (dis ? " disabled" : "") + ">"; o += "<span>" + v + "</span>"; if (c) { o += "<span class=" + QA + "c" + QA + ">" + c + "</span>"; } if (why) { o += "<span class=" + QA + "lk" + QA + ">" + why + "</span>"; } return o + "</button>"; }
function lock(id, v, why) { HAND[id] = null; var o = "<div class=" + QD + "f" + QD + " id=" + QD + id + QD + " aria-disabled=" + QD + "true" + QD + ">"; o += "<span>" + v + "</span><span class=" + QA + "lk" + QA + ">" + why + "</span></div>"; return o; }
// E7: in the reader role every mutating face is inert with the mirror reason; only Take over lives.
function rf(id, v, c, dis, fn, why) { if (S.role === "reader") { return lock(id, v, "This tab follows the other tab"); } return btn(id, v, c, null, dis, fn, why); }
function rows(pairs) { var h = "<div class=" + QA + "rows" + QA + ">"; for (var i = 0; i < pairs.length; i++) { h += "<i>" + pairs[i][0] + "</i><b>" + pairs[i][1] + "</b>"; } return h + "</div>"; }
function bar(v, max) { var p = Math.max(0, Math.min(100, Math.round((v / max) * 100))); return "<span class=" + QA + "fill" + QA + "><i style=" + QA + "width:" + p + "%" + QA + "></i></span>"; }
function tap(id) { S.pressed++; S.lastFace = id; var n = el(id); S.log.push({ n: S.pressed, id: id, label: n ? (n.textContent || "").trim() : id, band: bandOf(id) }); var h = HAND[id]; if (h) { h(); } render(); }
function bandOf(id) { if (id.indexOf("nav-") === 0) { return "nav"; } if (id.indexOf("tgl-") === 0) { return "cluster"; } if (id.indexOf("zoom-") === 0 || id === "canvas") { return "world"; } if (id.indexOf("key-") === 0) { return "keyboard"; } if (id.indexOf("nav") === 0) { return "nav"; } if (id === "gate-begin" || id === "take-over" || id.indexOf("action-") === 0 || id.indexOf("build-") === 0 || id.indexOf("fork-") === 0) { return "action"; } return "insp"; }
function key(k) { S.pressed++; S.log.push({ n: S.pressed, id: "key-" + k, label: k, band: "keyboard" }); if (k === "Escape") { pop(); return; } if (k === "n" || k === "N") { nextBp(); return; } if (k === "m" || k === "M") { if (S.data.machines.length) { openMachine(S.data.machines[0].id); } else { render(); } return; } render(); }
function tapCanvas(x, y) { S.pressed++; S.log.push({ n: S.pressed, id: "canvas", label: "world tap " + Math.round(x) + "," + Math.round(y), band: "world" }); if (S.blueprint !== null) { if (pick(x, y) !== null) { S.ghost = 8; } place(); return; } S.machine = pick(x, y); S.sub = 0; render(); }
function pick(x, y) { var box = el("world").getBoundingClientRect(); for (var i = 0; i < S.data.machines.length; i++) { var p = tilePt(S.data.machines[i].tile, box); if (Math.abs(p.x - x) < 26 && Math.abs(p.y - y) < 22) { return S.data.machines[i].id; } } return null; }
function tilePt(tile, box) { var cols = 4, s = Math.min(box.width / 5, box.height / 7) * S.zoom; var cx = box.width / 2, cy = box.height / 2 + s; var col = tile % cols, row = Math.floor(tile / cols); return { x: cx + (col - row) * s * 0.95, y: cy + (col + row) * s * 0.55 - s * 1.6 }; }
function flash(t) { S.toast = t; }
function push(id) { S.stack.push({ id: id, ret: S.lastFace || (document.activeElement && document.activeElement.id ? document.activeElement.id : null) }); S.hist = (S.hist || 0) + 1; try { history.pushState({ d: S.stack.length }, ""); } catch (e) { S.hist = S.stack.length; } }
function pop(fromHistory) { var top = S.stack.pop(); var ret = top ? top.ret : null; if (top) { if (top.id.indexOf("dest:") === 0) { S.dest = "yard"; } else if (top.id.indexOf("ent:") === 0) { S.machine = null; } else if (top.id.indexOf("sub:") === 0) { S.sub = 0; } else if (top.id.indexOf("page:") === 0) { S.importPage = false; } else if (top.id.indexOf("report") === 0) { S.report = false; } } if (!fromHistory && S.hist > 0) { S.hist -= 1; try { S.syncBack = 1; history.back(); } catch (e) { } } render(); if (ret && el(ret)) { try { el(ret).focus(); } catch (e) { } } }
function go(dest) { if (S.dest === dest) { return; } if (dest === "yard") { S.dest = "yard"; S.machine = null; S.sub = 0; S.stack.length = 0; S.hist = 0; } else { S.dest = dest; S.machine = null; S.sub = 0; push("dest:" + dest); } render(); }
function openMachine(id) { S.machine = id; S.sub = 0; if (S.dest === "yard") { push("ent:machine-" + id); } render(); }
function openSub(n) { S.sub = n; push("sub:" + n); render(); }
function addRow(name, qty) { for (var i = 0; i < S.data.rows.length; i++) { if (S.data.rows[i][0] === name) { S.data.rows[i][1] += qty; return; } } S.data.rows.push([name, qty]); }
function have(name) { for (var i = 0; i < S.data.rows.length; i++) { if (S.data.rows[i][0] === name) { return S.data.rows[i][1]; } } return 0; }
function salvage() { var d = S.data; d.scrap += 5; d.pulses += 1; addRow("Scrap", 5); if (d.pulses > 8) { addRow("Ferrous", 1); addRow("Nonferrous", 1); d.storeUnits += 2; } else { d.storeUnits += 5; } if (d.pulses >= 6 && d.tutorial <= 1) { d.tutorial = 2; } flash("Cutting pulse recharging"); }
function repair() { var d = S.data; if (d.scrap < 30) { flash("Need 30 scrap " + U.mid + " have " + d.scrap); return; } d.scrap -= 30; d.drone = true; d.tutorial = 3; }
function bpOf(b) { for (var i = 0; i < BP.length; i++) { if (BP[i].id === b) { return BP[i]; } } return BP[0]; }
function bpCost(b) { return bpOf(b).cost; }
function bpAfford(b) { var d = bpOf(b); return S.data.scrap >= d.scrap && have("Ferrous") >= d.ferrous; }
function pickBp(b) { if (!bpAfford(b)) { flash("Need " + bpCost(b) + " " + U.mid + " have " + S.data.scrap + " scrap"); return; } S.blueprint = b; S.ghost = (b === "sorter") ? 8 : 9; }
function nextBp() { if (S.blueprint === null) { return; } S.blueprint = (S.blueprint === "sorter") ? "furnace" : "sorter"; render(); }
function place() { var d = S.data; var b = S.blueprint || "sorter"; var def = bpOf(b); if (!bpAfford(b)) { flash("Need " + def.cost + " " + U.mid + " have " + d.scrap + " scrap"); return; } d.scrap -= def.scrap; if (def.ferrous) { for (var i = 0; i < d.rows.length; i++) { if (d.rows[i][0] === "Ferrous") { d.rows[i][1] = Math.max(0, d.rows[i][1] - def.ferrous); } } } d.storeUnits = Math.max(0, d.storeUnits - def.scrap - def.ferrous); d.machines.push({ id: d.machines.length + 1, n: def.n, tile: S.ghost, lvl: 1, cyc: "4.00s", rate: "0.00", max: "0.25", pw: "1 unit", need: "2 Scrap", next: "Needs 2 scrap, which nothing in the yard", up: "4.00s → 3.80s", price: 30, links: 0 }); S.blueprint = null; S.machine = d.machines[d.machines.length - 1].id; S.sub = 0; if (d.tutorial <= 6) { d.tutorial = 4; } }
function connect(id) { for (var i = 0; i < S.data.machines.length; i++) { if (S.data.machines[i].id === id) { S.data.machines[i].links = 1; } } S.data.links += 2; flash("Link open " + U.mid + " 1 route"); }
function sell(res) { var q = SELL_M[res][0], cr = SELL_M[res][1]; var d = S.data; var row = null; for (var i = 0; i < d.rows.length; i++) { if (d.rows[i][0] === res) { row = d.rows[i]; } } if (!row || row[1] < q) { flash("Need " + q + " units " + U.mid + " have " + (row ? row[1] : 0)); return; } row[1] -= q; d.storeUnits = Math.max(0, d.storeUnits - q); d.credits += cr; flash("Sold " + q + " " + res + " " + U.mid + " +" + cr + " credits"); }
function upgrade(branch, price) { var d = S.data; if (d.credits < price) { flash("Need " + price + " credits " + U.mid + " have " + d.credits); return; } d.credits -= price; for (var i = 0; i < d.machines.length; i++) { if (d.machines[i].id === S.machine) { d.machines[i].lvl += 1; d.machines[i].chosen = branch; } } flash("Upgraded " + branch); }
function buyNode(i) { var d = S.data; var cost = NODES[i][2]; if (d.data < cost) { flash("Need " + cost + " Data " + U.mid + " have " + d.data); return; } d.data -= cost; if (d.known.indexOf(i) < 0) { d.known.push(i); } }
function recordText() { var d = S.data; return "{" + QD + "schemaVersion" + QD + ":1," + QD + "tick" + QD + ":" + d.tick + "," + QD + "payload" + QD + ":{" + QD + "machines" + QD + ":" + d.machines.length + "," + QD + "links" + QD + ":" + d.links + "," + QD + "credits" + QD + ":" + d.credits + "}," + QD + "checksum" + QD + ":" + QD + "a91f3c" + QD + "}"; }
function copyRecord() { flash("Yard record copied " + U.mid + " " + recordText().length + " characters"); }
function openImport() { S.importPage = true; push("page:import"); }
function applyImport() { var v = (el("import-field") || {}).value || S.importText || ""; S.importText = v; S.importError = (v.length > 3 && v.indexOf("schemaVersion") >= 0) ? null : "Not a Rustwake file " + U.mid + " expected { schemaVersion 1, payload, checksum }"; }
function takeOver() { S.role = "writer"; flash("This tab now writes"); }
function zoomBy(k) { S.zoom = Math.max(1.2, Math.min(6, (S.zoom || 1.6) + k)); }
function machineOf() { for (var i = 0; i < S.data.machines.length; i++) { if (S.data.machines[i].id === S.machine) { return S.data.machines[i]; } } return null; }
function unconnected() { for (var i = 0; i < S.data.machines.length; i++) { if (!S.data.machines[i].links) { return S.data.machines[i].id; } } return null; }
function hasBp(name) { for (var i = 0; i < S.data.machines.length; i++) { if (S.data.machines[i].n === name) { return true; } } return false; }
function firstSell() { for (var i = 0; i < SELL_SEQ.length; i++) { var n = SELL_SEQ[i]; if (SELL_M[n] && have(n) >= SELL_M[n][0]) { return n; } } return null; }
function forkShown() { var m = machineOf(); return !!m && S.dest === "yard" && S.sub === 0 && (m.price || 0) > 0; }
